const views={history:['Histórico de listas','Listas finalizadas, com impressão e consulta por data.'],users:['Usuários','Gerencie os acessos e permissões da equipe.'],overview:['Visão geral','Sua rotina de reposição em um só lugar.'],restock:['Reposição','Monte listas e acompanhe cada etapa da separação.'],products:['Consulta produtos','Encontre produtos e consulte preço e saldo.'],quotes:['Orçamentos','Monte orçamentos com desconto, dados do cliente e observação.'],reports:['Relatórios','Acompanhe os produtos mais solicitados por período.'],settings:['Configurações','Gerencie seus dados e as preferências disponíveis para seu perfil.'],help:['Como usar','Aprenda na prática, no seu ritmo.']};
export function setupNavigation(){
 const $=id=>document.getElementById(id),sidebar=$('app-sidebar'),toggle=$('menu-toggle'),scrim=$('menu-scrim');let profile=null,current='overview';
 const collapse=$('sidebar-collapse');let collapsed=false;try{collapsed=localStorage.getItem('repoe-sidebar-collapsed')==='true';}catch{}
 function applyCollapse(){document.body.classList.toggle('sidebar-collapsed',collapsed);collapse.setAttribute('aria-expanded',String(!collapsed));const label=collapsed?'Expandir menu':'Recolher menu';collapse.setAttribute('aria-label',label);collapse.title=label;}
 collapse.onclick=()=>{collapsed=!collapsed;applyCollapse();try{localStorage.setItem('repoe-sidebar-collapsed',String(collapsed));}catch{}};applyCollapse();
 function closeMenu(focus=false){sidebar.classList.remove('is-open');scrim.hidden=true;toggle.setAttribute('aria-expanded','false');if(focus)toggle.focus();}
 function show(view,{focus=true}={}){if(!profile)return;view=views[view]?view:'overview';if(!profile.active&&!['settings','help','overview'].includes(view))view='overview';if(view==='users'&&(profile.role!=='admin'||!profile.active))view='overview';current=view;document.body.dataset.view=view;const [title,description]=views[view];$('workspace-title').textContent=title;$('workspace-description').textContent=view==='restock'&&['estoquista','admin'].includes(profile.role)?'Abra uma lista, inicie a separação e confirme o que está pronto.':description;
 for(const link of sidebar.querySelectorAll('[data-view]')){if(link.dataset.view===view)link.setAttribute('aria-current','page');else link.removeAttribute('aria-current');}
 $('reports-screen').hidden=view!=='reports'||!profile.active;$('quote-screen').hidden=view!=='quotes'||!profile.active;$('help-screen').hidden=view!=='help';if(view==='settings')$('account-panel').open=true;closeMenu();document.dispatchEvent(new CustomEvent('app:view-change',{detail:view}));if(focus){$('workspace-title').focus({preventScroll:true});window.scrollTo({top:0,behavior:'smooth'});}
 }
 sidebar.querySelectorAll('[data-view]').forEach(link=>link.addEventListener('click',e=>{e.preventDefault();if(link.getAttribute('aria-disabled')==='true')return;history.replaceState(null,'','#'+link.dataset.view);show(link.dataset.view);}));
 toggle.onclick=()=>{const open=!sidebar.classList.contains('is-open');sidebar.classList.toggle('is-open',open);scrim.hidden=!open;toggle.setAttribute('aria-expanded',String(open));if(open)sidebar.querySelector('[aria-current]')?.focus();};scrim.onclick=()=>closeMenu(true);document.addEventListener('keydown',e=>{if(e.key==='Escape'&&sidebar.classList.contains('is-open'))closeMenu(true);});window.addEventListener('hashchange',()=>show(location.hash.slice(1)));
 return {show,configure(next){profile=next;document.body.classList.toggle('signed-in',!!profile);sidebar.hidden=toggle.hidden=!profile;closeMenu();if(!profile){delete document.body.dataset.view;return;}$('sidebar-role').textContent=profile.role.toUpperCase();for(const link of sidebar.querySelectorAll('[data-view]')){link.hidden=link.dataset.view==='users'&&(profile.role!=='admin'||!profile.active);const blocked=!profile.active&&!['overview','settings','help'].includes(link.dataset.view);link.setAttribute('aria-disabled',String(blocked));}show(location.hash.slice(1)||current,{focus:false});}};
}
